// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address sender, uint256 amount) public {
        bound(amount, 0, type(uint128).max);
        vm.deal(sender, amount);
        uint256 balBefore = c.getBalance(sender);
        vm.prank(sender);
        c.addToBalance{value: amount}();
        uint256 balAfter = c.getBalance(sender);
        assertTrue(balAfter == balBefore + amount);
    }
}
